def count_divisors(n):
    if n == 0:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

solutions = []
for k in range(1, 31):
    n = 2 * (k**3)
    tau_n = count_divisors(n)
    target = 2 * k
    if tau_n == target:
        solutions.append(k)

print(f"Solutions found: {solutions}")
